import { Lease, Source } from './source';
import { mapEvent } from './mapper';

export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}

  /**
   * Lazily opens a lease on first iteration and yields mapped records in order.
   * The lease is closed exactly once when the stream finishes: on normal
   * exhaustion, consumer break/return, source read failure, mapper failure or a
   * consumer-injected throw. A close failure never masks an exception that is
   * already propagating (read, mapper or consumer-injected); otherwise the close
   * failure itself is propagated.
   */
  async *stream(): AsyncGenerator<string> {
    let lease: Lease | undefined;
    let propagating = false;
    try {
      lease = await this.source.open();
      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      // An exception (read, mapper or consumer-injected) is on its way out of the
      // body; remember it so a failing close cannot replace it below.
      propagating = true;
      throw error;
    } finally {
      const openLease = lease;
      lease = undefined;
      if (openLease !== undefined) {
        try {
          await openLease.close();
        } catch (closeError) {
          if (!propagating) throw closeError;
        }
      }
    }
  }
}
```

